// ─── PRIORITY DAILY DIGEST BUILDER ────────────────────────────────────────
//
// Column map (matches updated crm-setup.md schema):
//   A=Lead ID, B=Business Name, C=Industry, D=Contact Name, E=First Name
//   F=Email, G=Phone, H=Website, I=City, J=State, K=Contact Source
//   L=Personalization Note
//   M=Score:Ads, N=Score:Service, O=Score:Urgency, P=Score:Website, Q=Score:Contact
//   R=Lead Score, S=Priority Tier
//   T=Status, U=Initial Email Date, V=FU1 Date, W=FU2 Date, X=FU3 Date
//   Y=Last Contact Date, Z=Next Follow-Up Date
//   AA=Reply Received, AB=Reply Date, AC=Reply Type, AD=Reply Summary
//   AE=Meeting Date, AF=Outcome, AG=Notes

const items = $input.all();
const today = new Date();
today.setHours(0, 0, 0, 0);

// Terminal statuses — never include in digest
const CLOSED = new Set([
  'Booked', 'Not Interested', 'Lost',
  'Park - 90 Days', 'Park - 60 Days', 'Do Not Contact'
]);

// Priority sort order
const TIER_ORDER = { '🔴 HOT': 0, '🟠 WARM': 1, '🟡 COOL': 2, '⚪ COLD': 3 };

// ── Categorise every lead ───────────────────────────────────────────────
const urgentReplies = [];   // replied but status not yet updated
const dueHot = [];          // HOT leads due for follow-up today
const dueWarm = [];         // WARM leads due today
const dueCool = [];         // COOL leads due today
const overdue = [];         // any tier, overdue > 0 days
const newUncontacted = [];  // scored but never emailed (no Initial Email Date)

for (const item of items) {
  const lead = item.json;

  if (!lead['Business Name'] || !lead['Email']) continue;

  const status   = (lead['Status'] || 'New Lead').trim();
  const tier     = (lead['Priority Tier'] || '').trim();
  const score    = parseFloat(lead['Lead Score']) || 0;
  const replied  = lead['Reply Received'] === 'TRUE' || lead['Reply Received'] === true;
  const nextFUStr = lead['Next Follow-Up Date'];
  const initSent  = lead['Initial Email Date'];

  if (CLOSED.has(status)) continue;

  // Urgent: reply received but CRM status still in outreach stages
  const outreachStatuses = new Set(['Contacted','Follow-Up 1 Sent','Follow-Up 2 Sent','Follow-Up 3 Sent']);
  if (replied && outreachStatuses.has(status)) {
    urgentReplies.push(lead);
    continue;
  }
  if (replied) continue; // already in a post-reply stage, handled separately

  // New uncontacted leads (scored but never emailed) - surface HOT ones
  if (!initSent && score >= 8) {
    newUncontacted.push(lead);
    continue;
  }

  if (!nextFUStr) continue;

  const nextFUDate = new Date(nextFUStr);
  nextFUDate.setHours(0, 0, 0, 0);
  const diffDays = Math.floor((today - nextFUDate) / 86400000);

  if (diffDays < 0) continue; // future — not yet due

  const entry = { ...lead, _daysOverdue: diffDays, _score: score, _tier: tier };

  if (diffDays > 0) {
    overdue.push(entry);
  } else {
    if (tier === '🔴 HOT')   dueHot.push(entry);
    else if (tier === '🟠 WARM') dueWarm.push(entry);
    else                         dueCool.push(entry);
  }
}

// Sort overdue by tier then by how many days late
overdue.sort((a, b) => {
  const tierDiff = (TIER_ORDER[a._tier] || 3) - (TIER_ORDER[b._tier] || 3);
  return tierDiff !== 0 ? tierDiff : b._daysOverdue - a._daysOverdue;
});

// Sort new uncontacted by score desc
newUncontacted.sort((a, b) => (parseFloat(b['Lead Score']) || 0) - (parseFloat(a['Lead Score']) || 0));

// ── Build plain-text digest ────────────────────────────────────────────
const dateDisplay = today.toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const SEP = '─'.repeat(55);
let d = `OUTREACH PRIORITY DIGEST — ${dateDisplay}\n${'='.repeat(55)}\n\n`;

// ── Section 0: Urgent replies ─────────────────────────────────────────
if (urgentReplies.length > 0) {
  d += `⚡  REPLIES RECEIVED — respond within 2 hours (${urgentReplies.length})\n${SEP}\n`;
  for (const l of urgentReplies) {
    d += `  ${l['Business Name']} (${l['First Name'] || l['Contact Name']}) — ${l['Industry']}\n`;
    d += `  Email: ${l['Email']}\n`;
    d += `  Their reply: ${l['Reply Summary'] || '(not yet logged — check Gmail)'}\n`;
    d += `  Reply type: ${l['Reply Type'] || '(not yet classified)'}\n\n`;
  }
}

// ── Section 1: HOT leads due today ───────────────────────────────────
if (dueHot.length > 0) {
  d += `🔴  HOT — Follow-ups due today (${dueHot.length})\n${SEP}\n`;
  for (const l of dueHot) {
    d += `  [Score ${l._score}/10] ${l['Business Name']} (${l['First Name'] || l['Contact Name']})\n`;
    d += `  ${l['City']}, ${l['State']} | ${l['Industry']} | Status: ${l['Status']}\n`;
    d += `  Email: ${l['Email']}${l['Phone'] ? ' | Phone: ' + l['Phone'] : ''}\n`;
    d += `  Note: ${l['Personalization Note'] || '(none)'}\n\n`;
  }
}

// ── Section 2: WARM leads due today ──────────────────────────────────
if (dueWarm.length > 0) {
  d += `🟠  WARM — Follow-ups due today (${dueWarm.length})\n${SEP}\n`;
  for (const l of dueWarm) {
    d += `  [Score ${l._score}/10] ${l['Business Name']} (${l['First Name'] || l['Contact Name']})\n`;
    d += `  ${l['City']}, ${l['State']} | ${l['Industry']} | Status: ${l['Status']}\n`;
    d += `  Email: ${l['Email']}\n`;
    d += `  Note: ${l['Personalization Note'] || '(none)'}\n\n`;
  }
}

// ── Section 3: COOL leads due today ──────────────────────────────────
if (dueCool.length > 0) {
  d += `🟡  COOL — Follow-ups due today (${dueCool.length})\n${SEP}\n`;
  for (const l of dueCool) {
    d += `  [Score ${l._score}/10] ${l['Business Name']}\n`;
    d += `  ${l['City']}, ${l['State']} | ${l['Industry']} | ${l['Email']}\n\n`;
  }
}

// ── Section 4: Overdue ────────────────────────────────────────────────
if (overdue.length > 0) {
  d += `⚠   OVERDUE — missed follow-up window (${overdue.length})\n${SEP}\n`;
  for (const l of overdue) {
    d += `  ${l._tier} [${l._score}/10] ${l['Business Name']} — ${l._daysOverdue}d overdue\n`;
    d += `  Status: ${l['Status']} | ${l['Email']}\n\n`;
  }
}

// ── Section 5: New HOT leads never contacted ─────────────────────────
if (newUncontacted.length > 0) {
  d += `🆕  NEW HOT LEADS — email today (${newUncontacted.length})\n${SEP}\n`;
  for (const l of newUncontacted) {
    d += `  [Score ${l['Lead Score']}/10] ${l['Business Name']}\n`;
    d += `  ${l['City']}, ${l['State']} | ${l['Email']}\n`;
    d += `  Note: ${l['Personalization Note'] || '(write before sending)'}\n\n`;
  }
}

// ── Summary line ─────────────────────────────────────────────────────
const totalActions = urgentReplies.length + dueHot.length + dueWarm.length +
                     dueCool.length + overdue.length + newUncontacted.length;

d += `${'='.repeat(55)}\n`;
d += `TOTAL: ${totalActions} action${totalActions !== 1 ? 's' : ''} today\n`;
d += `  ⚡ Replies to handle:     ${urgentReplies.length}\n`;
d += `  🔴 HOT follow-ups:        ${dueHot.length}\n`;
d += `  🟠 WARM follow-ups:       ${dueWarm.length}\n`;
d += `  🟡 COOL follow-ups:       ${dueCool.length}\n`;
d += `  ⚠  Overdue:               ${overdue.length}\n`;
d += `  🆕 New HOT to email:      ${newUncontacted.length}\n`;

const subjectEmoji = urgentReplies.length > 0 ? '⚡' : (dueHot.length > 0 ? '🔴' : '📬');
const subjectLine  = urgentReplies.length > 0
  ? `⚡ ${urgentReplies.length} repl${urgentReplies.length === 1 ? 'y' : 'ies'} + ${dueHot.length + dueWarm.length} follow-ups due`
  : `${subjectEmoji} ${totalActions} outreach action${totalActions !== 1 ? 's' : ''} today — ${dueHot.length} HOT`;

return [{
  json: {
    digest: d,
    subjectLine,
    totalActions,
    urgentReplies:   urgentReplies.length,
    hotDue:          dueHot.length,
    warmDue:         dueWarm.length,
    coolDue:         dueCool.length,
    overdue:         overdue.length,
    newHotLeads:     newUncontacted.length,
    hasItems:        totalActions > 0
  }
}];
